// Unit tests for the JS port, verified value-for-value against the Go repo
// (expected values generated by `go test -run TestOracle -v` in the repo root).
// Run: node web/test/run-tests.mjs

import * as abi from '../public/js/abi.js';
import { selector, topic0 } from '../public/js/keccak.js';
import { chartShares, legendHTML } from '../public/js/chart.js';
import {
  sel, topicPoolCreated, callDataBalanceOf, dataWords,
  signedTick, decodeUintArray, encAddress,
} from '../public/js/abi.js';
import {
  selAggregate3, encodeAggregate3, decodeAggregate3, resultUint,
} from '../public/js/multicall.js';
import { getSqrtRatioAtTick, positionAmounts, Q96 } from '../public/js/v3math.js';
import { importClaimers, parseCSV, decimalToRaw, cumulativeClaimed, claimersFromEvents } from '../public/js/claims.js';
import { formatUnits, buildDuneCSV } from '../public/js/csv.js';

let failures = 0;
function eq(name, got, want) {
  const g = String(got), w = String(want);
  if (g === w) { console.log(`PASS ${name}`); }
  else { failures++; console.error(`FAIL ${name}\n  got  ${g}\n  want ${w}`); }
}

// ---- keccak: selectors/topics (from keccak_test.go + TestOracle) ----
eq('selector balanceOf', selector('balanceOf(address)'), '0x70a08231');
eq('selector totalSupply', selector('totalSupply()'), '0x18160ddd');
eq('selector decimals', selector('decimals()'), '0x313ce567');
eq('selector symbol', selector('symbol()'), '0x95d89b41');
eq('selector token0', selector('token0()'), '0x0dfe1681');
eq('selector token1', selector('token1()'), '0xd21220a7');
eq('selector getReserves', selector('getReserves()'), '0x0902f1ac');
eq('selector slot0', sel.slot0, '0x3850c7bd');
eq('selector stakedValues', sel.stakedValues, '0x4b937763');
eq('selector positions', sel.positions, '0x99fbab88');
eq('selector gauge', sel.gauge, selector('gauge()'));
eq('legacy gauges removed', 'gauges' in sel, false);
eq('selector tokenOfOwnerByIndex', sel.tokenOfOwnerByIndex, '0x2f745c59');
eq('topic Transfer', topic0('Transfer(address,address,uint256)'),
  '0xddf252ad1be2c89b69c2b068fc378daa952ba7f163c4a11628f55a4df523b3ef');
eq('topic Approval', topic0('Approval(address,address,uint256)'),
  '0x8c5be1e5ebec7d5bd14f71427d1e84f3dd0314c0f7b2291e5b200ac8c7c3b925');
eq('topic ClaimFees (excluded from claimed)', abi.topicClaimFees,
  '0x03b031f5c39fe0dd2d6857f1cfe1a48d30aeddd78cea5fcf92a8f792c77cdc53');
eq('topic ClaimIncentives', abi.topicClaimIncentives,
  '0x2d491e878db8f327cff1dbcaade1d69ccf5a3dc6bd35acf19a3ed9e1e624c440');
eq('topic IncentiveCreated', abi.topicIncentiveCreated,
  '0x71ea36aee81224d6ff4b1ae4ad8152480a6519812d2ad880c0f428211a54f9c6');
eq('topic CL PoolCreated', topicPoolCreated, topic0('PoolCreated(address,address,int24,address)'));
eq('legacy claim topic removed', 'topicClaimRewards' in abi, false);
eq('selector aggregate3', selAggregate3, '0x82ad56cb');

// Long-input keccak (spans >1 absorb block of 136 bytes).
eq('topic long-signature', topic0('IncentiveCreated(uint256,address,address,uint256,uint48,uint48)'.repeat(4)).length, 66);

// ---- TickMath vs Go oracle ----
const TICKS = {
  '-887272': '4295128739',
  '-100000': '533968626430936354154228408',
  '-50000': '6504256538020985011912221507',
  '-200': '78439868342809377387252074393',
  '-1': '79224201403219477170569942574',
  '0': Q96.toString(),
  '1': '79232123823359799118286999568',
  '200': '80024378775772204256025656563',
  '50000': '965075977353221155028623082916',
  '100000': '11755562826496067164730007768450',
  '887272': '1461446703485210103287273052203988822378723970342',
};
for (const [tick, want] of Object.entries(TICKS)) {
  eq(`sqrtRatioAtTick(${tick})`, getSqrtRatioAtTick(Number(tick)), want);
}

// ---- positionAmounts vs Go oracle ----
const sqrtP = getSqrtRatioAtTick(12345);
const liq = 123456789012345678901234n;
const POS = [
  [-887200, 887200, '66597834949115441832244', '228859973674583796773963'],
  [12000, 13000, '2145645110244652095471', '3913785416346730331918'],
  [-50000, 12000, '0', '214810971163532206561663'],
  [12400, 20000, '20995466310040587413563', '0'],
];
for (const [lo, hi, w0, w1] of POS) {
  const [a0, a1] = positionAmounts(sqrtP, lo, hi, liq);
  eq(`positionAmounts[${lo},${hi}].a0`, a0, w0);
  eq(`positionAmounts[${lo},${hi}].a1`, a1, w1);
}

// ---- encodeAggregate3 vs Go oracle (2 mixed calls) ----
const GO_ENCODED = '';
eq('encodeAggregate3', encodeAggregate3([
  { target: '0xa1a0b2e02b0e6830ad5a4a7211691200945d8919', data: callDataBalanceOf('0x28aa4f9ffe21365473b64c161b566c3cdead0108') },
  { target: '0xabe1f289107c20081f591bb3972b8289add64f6c', data: sel.slot0 },
]), GO_ENCODED);

// ---- decodeAggregate3 (hand-built payload, mirrors TestDecodeAggregate3) ----
const wordUint = (v) => BigInt(v).toString(16).padStart(64, '0');
{
  const val = wordUint(42);
  const elem0 = wordUint(1) + wordUint(0x40) + wordUint(32) + val;
  const elem1 = wordUint(0) + wordUint(0x40) + wordUint(0);
  const headArea = wordUint(0x40) + wordUint(0x40 + elem0.length / 2);
  const array = wordUint(2) + headArea + elem0 + elem1;
  const payload = '0x' + wordUint(0x20) + array;
  const res = decodeAggregate3(payload);
  eq('decodeAggregate3 len', res.length, 2);
  eq('decodeAggregate3 [0]', `${res[0].success},${resultUint(res[0])}`, 'true,42');
  eq('decodeAggregate3 [1]', `${res[1].success},${resultUint(res[1])}`, 'false,0');
}

// ---- signedTick (int24 two's complement in a 256-bit word) ----
eq('signedTick +100', signedTick(wordUint(100)), 100);
eq('signedTick -100', signedTick(((1n << 256n) - 100n).toString(16).padStart(64, '0')), -100);

// ---- decodeUintArray ----
eq('decodeUintArray', decodeUintArray('0x' + wordUint(0x20) + wordUint(2) + wordUint(7) + wordUint(9)).join(','), '7,9');

// ---- claimers import: dedupe + MIN_CLAIMED (the repo's bug-fix #3) ----
{
  const csv = 'wallet,claimed_raw,claimed_decimal\r\n' +
    '0xAAA1000000000000000000000000000000000001,1500000000000000000000000,1500000\r\n' +
    '0xaaa1000000000000000000000000000000000001,600000000000000000000000,600000\r\n' + // dup row, different case
    '0xbbb2000000000000000000000000000000000002,999999000000000000000000,999999\r\n';  // below threshold
  const cl = importClaimers(csv, { decimals: 18, minClaimed: '1000000' });
  eq('importClaimers dedupe count', cl.length, 1);
  eq('importClaimers summed raw', cl[0].raw, 2100000000000000000000000n);
}
// Decimal-only layout fallback (snapshot CSV: wallet,partner,claimed).
{
  const csv = 'wallet,partner,claimed\n0xccc3000000000000000000000000000000000003,,2000000.5\n';
  const cl = importClaimers(csv, { decimals: 18, minClaimed: '1000000' });
  eq('importClaimers decimal fallback', cl[0].raw, 2000000500000000000000000n);
}

// ---- cumulative claimed ramp ----
{
  const evs = [
    { wallet: '0xa', block: 10n, amount: 5n },
    { wallet: '0xa', block: 20n, amount: 7n },
    { wallet: '0xb', block: 15n, amount: 100n },
  ];
  eq('cumulative @10', cumulativeClaimed(evs, 10n).get('0xa'), 5n);
  eq('cumulative @19 b', cumulativeClaimed(evs, 19n).get('0xb'), 100n);
  eq('cumulative @20', cumulativeClaimed(evs, 20n).get('0xa'), 12n);
  const cls = claimersFromEvents(evs, { decimals: 0, minClaimed: '6' });
  eq('claimersFromEvents', cls.map((c) => c.wallet).join(','), '0xb,0xa');
}

// ---- plain-decimal formatting (the Dune scientific-notation bug) ----
eq('formatUnits big', formatUnits(172000000000000000000000000n, 18), '172000000');
eq('formatUnits frac', formatUnits(1500000000000000000n, 18), '1.5');
eq('formatUnits tiny', formatUnits(1n, 18), '0.000000000000000001');
eq('formatUnits neg', formatUnits(-2500000000000000000n, 18), '-2.5');
eq('formatUnits zero', formatUnits(0n, 18), '0');
eq('decimalToRaw sci', decimalToRaw('1.7e+8', 18), 170000000000000000000000000n);
{
  const csvText = buildDuneCSV([{
    block: 47050128n, timestamp: 1723180800,
    rows: [{ wallet: '0xa', claimed: 172000000000000000000000000n, hold: 1000000000000000000n, lp: 0n }],
  }], 18, 'TEA');
  eq('duneCSV no scientific notation', /[0-9]e[+-]?[0-9]/i.test(csvText), false);
  eq('duneCSV header', csvText.split('\r\n')[0], 'block,timestamp,wallet,partner,claimed,TEA_LP,TEA_Hold,outflow');
  eq('duneCSV outflow', csvText.split('\r\n')[1].split(',')[7], '171999999');
}

// ---- CSV parser quoting ----
eq('parseCSV quotes', JSON.stringify(parseCSV('a,b\n"x,1","y""z"\n').rows), '[["x,1","y\\"z"]]');

// ---- encAddress padding ----
eq('encAddress', encAddress('0xA1A0b2e02b0e6830AD5a4a7211691200945d8919'),
  '000000000000000000000000a1a0b2e02b0e6830ad5a4a7211691200945d8919');
eq('dataWords', dataWords('0x' + wordUint(1) + wordUint(2)).length, 2);

const shareFixture = {
  claimed: 165750115405224905335324n,
  hold: 60532111582117846096331n,
  lp: 55105008916621963815606n,
  outflow: 50112994906485095423387n,
};
eq('chart share Hold', chartShares(shareFixture).hold, '36.52%');
eq('chart share LP', chartShares(shareFixture).lp, '33.25%');
eq('chart share Transfer out', chartShares(shareFixture).outflow, '30.23%');
eq('chart zero-claimed share', chartShares({ claimed: 0n, hold: 1n, lp: 2n, outflow: -3n }).hold, '0.00%');
const percentageLegend = legendHTML('RSGP', shareFixture);
eq('chart legend includes LP percentage', percentageLegend.includes('33.25%'), true);
eq('chart legend includes Hold percentage', percentageLegend.includes('36.52%'), true);
eq('chart legend includes Transfer out percentage', percentageLegend.includes('30.23%'), true);

try {
  const { runAeroTests } = await import('./aero.test.mjs');
  await runAeroTests();
} catch (error) { failures++; console.error('FAIL Aero integration', error); }

try {
  const { runUIConfigTests } = await import('./ui-config.test.mjs');
  await runUIConfigTests();
} catch (error) { failures++; console.error('FAIL UI/config integration', error); }

try {
  await import('../public/js/pipeline.js');
  console.log('PASS pipeline module imports with Aero-only ABI');
} catch (error) { failures++; console.error('FAIL pipeline module import', error); }

console.log(failures ? `\n${failures} FAILURES` : '\nALL TESTS PASSED');
process.exit(failures ? 1 : 0);
